      form.backupServerPort.value = "9090";
      form.apiMode.value = "auto";
      form.apiVersion.value = "auto";
      form.reportRange.value = "24h";
      customStartDate.value = "";
      customEndDate.value = "";
      syncRangeToToolbar();
      form.timeoutSeconds.value = "30";
